#!/bin/bash
## Claim-10 pulse test, MAGICC-SLR stage (Marcus 2026-11-17): MAGICC v7.5.3, 600 drawnset members, van Vuuren emissions
## to 2500 (slr_vv_and_ssps_to2500.csv), pulses in 2030 and 2080, six markers, CO2 1 GtCO2 / CH4 0.01 GtCH4, set
## `headlinepos` (baseline + pulse; the zero and sign-flip controls are replaced by the downstream bit-identity check
## against the shipped 2030 headline run through 2299). MAGICC is members-only and stays on this machine: Torch is not
## an option. Run from a FROZEN copy of 302e; do not edit this file while it runs.
set -uo pipefail
cd "$(dirname "$0")"
FTF=$(cd ../FaIRtoFrEDI && pwd); MAG=$(cd ../MAGICC/slr-refresh && pwd)
PY=~/miniforge3/envs/slr-refresh-2025/bin/python
MAGICC_WORKERS=6
LOG=$PWD/outputs/log_vv_pulse2500_20261117.txt
say(){ echo "[$(date '+%m-%d %H:%M:%S')] $*" | tee -a "$LOG"; }
step(){ local nm="$1" lg="$2"; shift 2; say "START  $nm"
  if "$@" >> "$lg" 2>&1; then say "OK     $nm"; else say "FAILED $nm (rc=$?)"; echo "$nm" >> "$LOG.fails.magicc"; fi; }
rm -f "$LOG.fails.magicc"
lg=$PWD/outputs/log_vv_pulse2500_magicc.txt; : > "$lg"
cp "$MAG/notebooks/302e_run-magicc-pulse-vv-to2500.py" "$MAG/notebooks/_frozen_302e_20261117.py"
for Y in 2030 2080; do for M in VL L ML M HL H; do for gas in co2 ch4; do
  step "scenario vv$M $gas p$Y to2500" "$lg" bash -c "cd '$FTF' && $PY magicc_comparison/build_pulse_scenarios_vv.py --marker=$M --gas=$gas --set=headlinepos --snap --pulse-year=$Y --to2500"
  step "MAGICC vv$M $gas p$Y to2500 (n600)" "$lg" bash -c "cd '$MAG/notebooks' && MAGICC_WORKER_NUMBER=$MAGICC_WORKERS MAGICC_VV_MARKER=$M \
    MAGICC_PULSE_GAS=$gas MAGICC_VV_SET=headlinepos MAGICC_PULSE_NCFGS=600 MAGICC_PULSE_YEAR=$Y MAGICC_TO2500=1 $PY _frozen_302e_20261117.py"
done; done; done
say "magicc phase done, $(cat "$LOG.fails.magicc" 2>/dev/null | wc -l | tr -d ' ') failures"
